from scipy.optimize import least_squares
def model(p,kind):
    y=p[0]*t*np.exp(-p[1]*t)*A**2 + p[2]*np.exp(-p[3]*t**2)
    if kind==0: y=y+p[4]
    if kind==1: y=y+p[4]*A
    if kind==2: y=y+p[4]*A**p[5]
    if kind==3: y=y+p[4]*np.exp(-p[5]*A)
    if kind==4: y=y+p[4]*t*A
    if kind==5: y=y+p[4]*np.exp(-p[5]*t)*A
    return y
