 'expA':lambda p: p[4]*np.exp(-p[5]*A),
 'A expA':lambda p: p[4]*A*np.exp(-p[5]*A),
 'texpA':lambda p: p[4]*t*np.exp(-p[5]*A),
 'expA t^p':lambda p: p[4]*t**p[6]*np.exp(-p[5]*A),
 'A^p expA':lambda p: p[4]*A**p[6]*np.exp(-p[5]*A),
 'expA expt':lambda p: p[4]*np.exp(-p[5]*A)*np.exp(-p[6]*t),
 'expA sin':lambda p: p[4]*np.exp(-p[5]*A)*np.cos(p[6]*t),
 'expA/t':lambda p: p[4]*np.exp(-p[5]*A)/t**p[6],
}
for k,f in V.items():
    bb=None
    for s in range(40):
        p0=np.random.RandomState(s).uniform(-2,2,7)
        def m(p): return p[0]*t*np.exp(-p[1]*t)*A**2 + p[2]*np.exp(-p[3]*t**2) + f(p)
        try:
            fr=least_squares(lambda p: m(p)-dA_dt,p0)
